#!/usr/bin/env bash
# СУДИТ: hooks/session-collector.sh
# probe_D1183 — строка долга «🧬 Класс опознан, а РЕЕСТР НОСИТЕЛЕЙ не назван…» доходит до очереди напоминаний один раз
# на ХОД, что бы ни звучало раньше в той же сессии. Дроссель свода (ключ `_sc_kinds` — состав постоянных напоминаний)
# «🧬» не знал: долг второго хода (и первый долг после любого постоянного напоминания) получал тот же ключ, что
# прежний Stop, и очередь его молча теряла — долг записан как `owed`, напоминания нет. Ход, продолженный после
# перезапуска хуком Stop, — тот же ход: его текст вырос, но второй строки долга он не даёт (второй круг, M-1).
# Счёт — вхождениями, а не строками очереди: все напоминания одного Stop лежат на одной строке (L-2).
# Красная (1), пока долг хода теряется или дублируется; 2 — свода или jq нет.
. "$(dirname "$0")/../alerts-read.sh"
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
COLL="$R/hooks/session-collector.sh"
[ -f "$COLL" ] && command -v jq >/dev/null 2>&1 || exit 2
T=$(mktemp -d); mkdir -p "$T/state"; trap 'rm -rf "$T"' EXIT
mk() {   # mk <uuid реплики> <реплика> <текст агента> <файл>
    jq -cn --arg u "$1" --arg r "$2" '{type:"user",uuid:$u,message:{role:"user",content:[{type:"text",text:$r}]}}' > "$4"
    jq -cn --arg t "$3" '{type:"assistant",message:{role:"assistant",content:[{type:"text",text:$t}]}}' >> "$4"
}
stop() { jq -cn --arg p "$1" '{session_id:"p1183", transcript_path:$p, hook_event_name:"Stop"}' \
    | STATE_DIR="$T/state" CLAUDSOUL_REPO="$R" CLAUDSOUL_ROOT="$R" CLAUDSOUL_BACKLOG="$T/none.md" bash "$COLL" >/dev/null 2>&1; }
owed() { alerts_of "$T/state" | grep -o 'РЕЕСТР НОСИТЕЛЕЙ' | wc -l | tr -d ' '; }
mk u-a 'чини первое' "Это тот же класс, что чинили утром. Правлю на месте." "$T/a.jsonl"
mk u-b 'чини второе' "Снова тот же класс, что вчера. Правлю и это на месте." "$T/b.jsonl"
stop "$T/a.jsonl"; first=$(owed)
stop "$T/b.jsonl"; second=$(owed)
[ "$first" != 0 ] || { echo "долг первого хода не дошёл до очереди — рамка не воспроизвела долг"; exit 2; }
[ "$first" = 1 ] || { echo "долг первого хода задвоен: строк долга в очереди $first из 1"; exit 1; }
[ "$second" = 2 ] || { echo "долг второго хода той же сессии потерян или задвоен: строк долга в очереди $second из 2"; exit 1; }
# Повтор того же события — повторный Stop на неизменном тексте — строки не добавляет.
stop "$T/b.jsonl"; third=$(owed)
[ "$third" = 2 ] || { echo "повторный Stop того же хода продублировал долг: строк долга в очереди $third из 2"; exit 1; }
# Ход продолжен после перезапуска хуком Stop: дописана реплика агента, реестр по-прежнему не назван — ход тот же.
jq -cn '{type:"assistant",message:{role:"assistant",content:[{type:"text",text:"Продолжаю правку на месте."}]}}' >> "$T/b.jsonl"
stop "$T/b.jsonl"; fourth=$(owed)
[ "$fourth" = 2 ] || { echo "продолженный ход продублировал долг: строк долга в очереди $fourth из 2"; exit 1; }
# Новый ход с тем же текстом агента, что у прежнего, — свой долг (третий круг, L-1: запись дедуплицировалась по тексту
# на всю сессию, и такой ход не получал ни записи, ни строки).
mk u-c 'чини третье' "Снова тот же класс, что вчера. Правлю и это на месте." "$T/c.jsonl"
stop "$T/c.jsonl"; fifth=$(owed)
[ "$fifth" = 3 ] || { echo "ход с тем же текстом, что у прежнего, долга не получил: строк долга в очереди $fifth из 3"; exit 1; }
echo "долг каждого хода доходит до очереди, один раз на ход"
